import{_ as e,o as i,c as a,a9 as s}from"./chunks/framework.DiSH7Fw_.js";const p=JSON.parse('{"title":"VS Code configuration","description":"","frontmatter":{},"headers":[],"relativePath":"interfaces/vscode-configuration.md","filePath":"interfaces/vscode-configuration.md","lastUpdated":null}'),r={name:"interfaces/vscode-configuration.md"};function n(d,t,o,l,c,g){return i(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="VS-Code-configuration" tabindex="-1">VS Code configuration <a class="header-anchor" href="#VS-Code-configuration" aria-label="Permalink to &quot;VS Code configuration {#VS-Code-configuration}&quot;">​</a></h1><p>Configure PerfChecker for the package folder you are measuring. In a multi-root workspace, use folder settings so one package cannot inherit another package&#39;s environment by accident.</p><h2 id="Choose-Julia-environments" tabindex="-1">Choose Julia environments <a class="header-anchor" href="#Choose-Julia-environments" aria-label="Permalink to &quot;Choose Julia environments {#Choose-Julia-environments}&quot;">​</a></h2><p>PerfChecker resolves <code>runnerProject</code> relative to the selected package folder. Its default is <code>perf</code>. If that default is unchanged and <code>perf/Project.toml</code> is absent, <code>perf/controller</code> is used when its project exists. An explicit setting always wins. <code>scenarioProject</code> follows the same default fallback for shared scenario workers.</p><p>The controller needs PerfChecker and the interface/provider packages used by the request. The target environment needs the measured package, its dependencies and any analyzer selected for target workers. Existing TestItems need TestItemRunner and their test dependencies in the selected runner environment.</p><p>Example folder settings, with an existing controller and target project:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;perfchecker.juliaExecutable&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;julia&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;perfchecker.runnerProject&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;perf/controller&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;perfchecker.scenarioProject&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;perfchecker.suite&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;perf/suite.jl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;perfchecker.scenarioCatalog&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;perf/scenarios.toml&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;perfchecker.scenarioSamples&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;perfchecker.scenarioThreads&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;perfchecker.analysisTools&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;jet&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;latency&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>An absolute environment path is also accepted. <code>juliaExecutable</code> is an executable path or launcher, not a shell command with additional arguments. PerfChecker supplies startup, history, project and worker arguments itself. No environment is installed merely by opening Studio.</p><h2 id="Core-and-suite-settings" tabindex="-1">Core and suite settings <a class="header-anchor" href="#Core-and-suite-settings" aria-label="Permalink to &quot;Core and suite settings {#Core-and-suite-settings}&quot;">​</a></h2><p>All setting names below have the prefix <code>perfchecker.</code>.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Setting</th><th style="text-align:right;">Default</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>juliaExecutable</code></td><td style="text-align:right;"><code>julia</code></td><td style="text-align:right;">Julia executable or juliaup launcher</td></tr><tr><td style="text-align:right;"><code>runnerProject</code></td><td style="text-align:right;"><code>perf</code></td><td style="text-align:right;">Controller project; default-only fallback to <code>perf/controller</code></td></tr><tr><td style="text-align:right;"><code>suite</code></td><td style="text-align:right;"><code>perf/suite.jl</code></td><td style="text-align:right;">Julia suite file relative to the selected folder</td></tr><tr><td style="text-align:right;"><code>factory</code></td><td style="text-align:right;"><code>build_suite</code></td><td style="text-align:right;">Zero-argument function constructing the suite</td></tr><tr><td style="text-align:right;"><code>profile</code></td><td style="text-align:right;"><code>quick</code></td><td style="text-align:right;">Suite execution profile</td></tr><tr><td style="text-align:right;"><code>reports</code></td><td style="text-align:right;"><code>perf/results/vscode</code></td><td style="text-align:right;">Saved suite reports</td></tr><tr><td style="text-align:right;"><code>uiConfiguration</code></td><td style="text-align:right;"><code>perf/perfchecker-ui.json</code></td><td style="text-align:right;">Shared visual suite selection</td></tr><tr><td style="text-align:right;"><code>gitTargets</code></td><td style="text-align:right;"><code>[]</code></td><td style="text-align:right;">Named branches, tags or commits measured alongside other targets</td></tr><tr><td style="text-align:right;"><code>comparisonPolicies</code></td><td style="text-align:right;"><code>[]</code></td><td style="text-align:right;">Exact or grouped baseline policies</td></tr></tbody></table><p>The visual suite editor manages the richer selection. See <a href="./../reference/comparisons">comparison configuration</a> for policy fields and aggregation semantics.</p><h2 id="Existing-TestItems" tabindex="-1">Existing TestItems <a class="header-anchor" href="#Existing-TestItems" aria-label="Permalink to &quot;Existing TestItems {#Existing-TestItems}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Setting</th><th style="text-align:right;">Default</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>testItemTags</code></td><td style="text-align:right;"><code>[]</code></td><td style="text-align:right;">Match any selected tag; empty selects all except <code>test_only</code></td></tr><tr><td style="text-align:right;"><code>testItemExcludeTags</code></td><td style="text-align:right;"><code>[]</code></td><td style="text-align:right;">Additional tags excluded from performance runs</td></tr><tr><td style="text-align:right;"><code>testItemSamples</code></td><td style="text-align:right;"><code>1</code></td><td style="text-align:right;">Explicit repetitions, each in a fresh process</td></tr></tbody></table><p>There is no automatic warmup of a native test item. The repetitions affect both scope and cost. Read <a href="./../test-items">TestItems and tags</a> before reusing functional tests as performance workloads.</p><h2 id="Shared-scenarios-and-analyzers" tabindex="-1">Shared scenarios and analyzers <a class="header-anchor" href="#Shared-scenarios-and-analyzers" aria-label="Permalink to &quot;Shared scenarios and analyzers {#Shared-scenarios-and-analyzers}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Setting</th><th style="text-align:right;">Default</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>scenarioCatalog</code></td><td style="text-align:right;"><code>perf/scenarios.toml</code></td><td style="text-align:right;">Explicit scenario catalogue</td></tr><tr><td style="text-align:right;"><code>scenarioProject</code></td><td style="text-align:right;"><code>perf</code></td><td style="text-align:right;">Worker environment for measurements and analyzers</td></tr><tr><td style="text-align:right;"><code>scenarioSamples</code></td><td style="text-align:right;"><code>10</code></td><td style="text-align:right;">Fresh-state samples per scenario and collector</td></tr><tr><td style="text-align:right;"><code>scenarioThreads</code></td><td style="text-align:right;"><code>1</code></td><td style="text-align:right;">Julia threads per scenario worker</td></tr><tr><td style="text-align:right;"><code>analysisTools</code></td><td style="text-align:right;"><code>[&quot;jet&quot;, &quot;alloccheck&quot;, &quot;latency&quot;]</code></td><td style="text-align:right;">Default requested analyzers</td></tr><tr><td style="text-align:right;"><code>analysisTimeout</code></td><td style="text-align:right;"><code>120</code></td><td style="text-align:right;">Worker deadline in seconds</td></tr><tr><td style="text-align:right;"><code>investigationReports</code></td><td style="text-align:right;"><code>perf/results/investigations</code></td><td style="text-align:right;">Saved investigation evidence</td></tr><tr><td style="text-align:right;"><code>investigationMaxExperiments</code></td><td style="text-align:right;"><code>4</code></td><td style="text-align:right;">Maximum declared experiments per investigation</td></tr><tr><td style="text-align:right;"><code>investigationBudgetSeconds</code></td><td style="text-align:right;"><code>300</code></td><td style="text-align:right;">Total investigation deadline, including requests/startup</td></tr></tbody></table><p>Unavailable is separate from passing or failing. Remove a tool you do not need, or explicitly install it in the prepared worker environment. PerfChecker will not silently install it for you.</p><h2 id="Advice-and-MCP-settings" tabindex="-1">Advice and MCP settings <a class="header-anchor" href="#Advice-and-MCP-settings" aria-label="Permalink to &quot;Advice and MCP settings {#Advice-and-MCP-settings}&quot;">​</a></h2><p>Use <strong>PerfChecker: Configure advisor and manage models</strong> to check the connection, discover MCP tools and save configuration. For chat, select <code>mcp_http</code>, a tool that accepts an advice request, and <code>text</code> response mode. A tool named <code>ask</code> is only an example; MCP defines no standard chat-tool name.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Setting</th><th style="text-align:right;">Default</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>advisorEnabled</code></td><td style="text-align:right;"><code>true</code></td><td style="text-align:right;">Permits explicitly requested optional advice</td></tr><tr><td style="text-align:right;"><code>advisorConfig</code></td><td style="text-align:right;">empty</td><td style="text-align:right;">JSON config path; takes precedence over provider settings</td></tr><tr><td style="text-align:right;"><code>advisorProtocol</code></td><td style="text-align:right;"><code>chat_completions</code></td><td style="text-align:right;">Provider protocol; chat requires <code>mcp_http</code></td></tr><tr><td style="text-align:right;"><code>advisorEndpoint</code></td><td style="text-align:right;">local Chat Completions URL</td><td style="text-align:right;">Existing model or MCP endpoint</td></tr><tr><td style="text-align:right;"><code>advisorModel</code></td><td style="text-align:right;"><code>local</code></td><td style="text-align:right;">Provider model identifier; not an installation</td></tr><tr><td style="text-align:right;"><code>advisorInstructions</code></td><td style="text-align:right;">empty</td><td style="text-align:right;">Prompt customization, up to 5,000 characters</td></tr><tr><td style="text-align:right;"><code>advisorMcpTool</code></td><td style="text-align:right;">empty</td><td style="text-align:right;">Explicit advice tool</td></tr><tr><td style="text-align:right;"><code>advisorMcpPromptArgument</code></td><td style="text-align:right;"><code>prompt</code></td><td style="text-align:right;">Argument receiving instructions and bounded context</td></tr><tr><td style="text-align:right;"><code>advisorMcpArguments</code></td><td style="text-align:right;"><code>{}</code></td><td style="text-align:right;">Required extra arguments; no prompt override/secrets</td></tr><tr><td style="text-align:right;"><code>advisorMcpResponse</code></td><td style="text-align:right;"><code>text</code></td><td style="text-align:right;">Unverified text, or structured evidence references</td></tr><tr><td style="text-align:right;"><code>advisorMcpVersion</code></td><td style="text-align:right;"><code>2026-07-28</code></td><td style="text-align:right;">Explicit supported MCP protocol revision</td></tr><tr><td style="text-align:right;"><code>advisorAllowRemote</code></td><td style="text-align:right;"><code>false</code></td><td style="text-align:right;">Allows transmission to a remote HTTPS endpoint</td></tr><tr><td style="text-align:right;"><code>advisorKeyEnvironment</code></td><td style="text-align:right;">empty</td><td style="text-align:right;">Name of the environment variable containing the token</td></tr><tr><td style="text-align:right;"><code>advisorTimeout</code></td><td style="text-align:right;"><code>90</code></td><td style="text-align:right;">Total provider-worker deadline in seconds</td></tr><tr><td style="text-align:right;"><code>advisorInvestigates</code></td><td style="text-align:right;"><code>false</code></td><td style="text-align:right;">Structured model selection of declared experiments</td></tr></tbody></table><p>Disabling <code>advisorEnabled</code> keeps deterministic advice usable and retains already installed model files. <a href="/PerfChecker/v1.0.0/mcp-advisor#Configure-the-advice-tool">MCP configuration</a> includes complete JSON and VS Code examples.</p><h2 id="Implementation-settings" tabindex="-1">Implementation settings <a class="header-anchor" href="#Implementation-settings" aria-label="Permalink to &quot;Implementation settings {#Implementation-settings}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Setting</th><th style="text-align:right;">Default</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><code>advisorImplementationMcpTool</code></td><td style="text-align:right;">empty</td><td style="text-align:right;">Separate tool authorized after reviewed advice and confirmation</td></tr><tr><td style="text-align:right;"><code>advisorImplementationMcpPromptArgument</code></td><td style="text-align:right;"><code>prompt</code></td><td style="text-align:right;">Implementation prompt argument</td></tr><tr><td style="text-align:right;"><code>advisorImplementationMcpWorkspaceArgument</code></td><td style="text-align:right;"><code>workspace</code></td><td style="text-align:right;">Isolated checkout argument</td></tr></tbody></table><p>Implementation reuses the MCP endpoint, revision, authentication and extra arguments. Its tool and prompt/workspace names are explicit extension settings; an advice reply cannot select them automatically. Prompt and workspace names must differ. Extra arguments cannot override either reserved field.</p><p>The server must access the isolated checkout. A remote HTTPS endpoint has no automatic access to your local filesystem. Use a trusted local tool, or a deliberately configured shared filesystem/bridge with its own confinement. MCP does not provide an operating-system sandbox.</p><h2 id="Troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#Troubleshooting" aria-label="Permalink to &quot;Troubleshooting {#Troubleshooting}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Problem</th><th style="text-align:right;">Resolution</th></tr></thead><tbody><tr><td style="text-align:right;">Project does not exist</td><td style="text-align:right;">Check the selected folder and <code>Project.toml</code>; use an absolute path</td></tr><tr><td style="text-align:right;">Suite factory missing</td><td style="text-align:right;">Verify the configured suite file and function name</td></tr><tr><td style="text-align:right;">Tool package absent</td><td style="text-align:right;">Install deliberately into the environment selected for that worker</td></tr><tr><td style="text-align:right;">Chat asks for MCP text mode</td><td style="text-align:right;">Update the JSON config if <code>advisorConfig</code> is set; it overrides provider settings</td></tr><tr><td style="text-align:right;">Credentials absent</td><td style="text-align:right;">Start VS Code with the named environment variable available to its extension host</td></tr><tr><td style="text-align:right;">Probe passes, chat fails</td><td style="text-align:right;">Check required tool arguments and that the selected tool returns advice</td></tr><tr><td style="text-align:right;">Agent cannot see the code</td><td style="text-align:right;">Check access to the supplied isolated checkout, not the original root</td></tr><tr><td style="text-align:right;">Notebook cannot execute</td><td style="text-align:right;">Select an installed Julia kernel; see <a href="/PerfChecker/v1.0.0/interfaces/vscode-workflows#Investigation-notebooks">notebook prerequisites</a></td></tr></tbody></table><p>Worker logs are available through <strong>PerfChecker: Show worker output</strong>. Keep tokens out of configuration files and troubleshooting reports.</p>`,29)])])}const y=e(r,[["render",n]]);export{p as __pageData,y as default};
